import numpy as np
x=np.load('source_pixels.npz')['rgb'].astype(np.int16)
# masks by relative channels
R=x[:,:,:,0]; G=x[:,:,:,1]; B=x[:,:,:,2]
masks={
 'red': (R>100)&(R>G*1.5)&(R>B*1.4),
 'green': (G>80)&(G>R*1.25)&(G>B*1.15),
 'white': (R>190)&(G>190)&(B>190)&(np.max(x,axis=3)-np.min(x,axis=3)<35),
 'yellow':(R>120)&(G>100)&(B<100),
 'blue':(B>100)&(B>R*1.3)&(B>G*1.2),
}
for name,m in masks.items():
 print('\\n',name,'total',m.sum())
 for i in [0,1,12,24,36,48,60,72,84,95]:
  ys,xs=np.where(m[i])
  if len(xs): print(i,len(xs),'bbox',xs.min(),ys.min(),xs.max(),ys.max(),'cen',round(xs.mean(),1),round(ys.mean(),1))
  else: print(i,0)
