import cv2,numpy as np
cap=cv2.VideoCapture('source_video.mp4');ok,fr=cap.read();rgb=cv2.cvtColor(fr,cv2.COLOR_BGR2RGB)
# inspect scene objects at native: approximate ROI corresponding x 130-190 y50-80 => x650-950 y250-400
# list connected components with hue for green/cyan etc in central region
hsv=cv2.cvtColor(fr,cv2.COLOR_BGR2HSV)
for h0,h1,name in [(35,85,'green'),(85,135,'blue'),(0,12,'red'),(150,180,'pink'),(13,34,'yellow')]:
 if h0==0: m=((hsv[:,:,0]>=h0)&(hsv[:,:,0]<=h1)&(hsv[:,:,1]>60))
 else: m=((hsv[:,:,0]>=h0)&(hsv[:,:,0]<=h1)&(hsv[:,:,1]>60))
 m=m.astype('uint8');n,lab,st,cent=cv2.connectedComponentsWithStats(m,8)
 print('\\n',name,'total',m.sum())
 for j in sorted(range(1,n),key=lambda j:st[j,4],reverse=True)[:20]:
  x,y,w,h,a=st[j]
  if a>=100: print(int(a),(int(x),int(y),int(w),int(h)),tuple(np.round(cent[j],1)),np.round(np.median(rgb[lab==j],axis=0),1))
