/bin/bash -c "python - <<'PY'
import numpy as np
x=np.load('source_pixels.npz')['rgb']
f=x[0]
# print actual patch around green and candidate white
for name,(x0,x1,y0,y1) in {'green':(158,178,50,75),'whiteA':(118,140,65,87),'whiteB':(96,118,70,91),'red':(18,50,56,84)}.items():
 print('\\n'+name)
 for y in range(y0,y1):
  row=[]
  for xx in range(x0,x1):
   r,g,b=map(int,f[y,xx]);
   if name=='green': c='G' if b-r>25 else ('g' if b-r>8 else ('W' if min(r,g,b)>170 else '.'))
   elif name=='red': c='R' if r-g>30 else ('r' if r-g>12 else ('W' if min(r,g,b)>170 else '.'))
   else: c='W' if min(r,g,b)>220 else ('w' if min(r,g,b)>190 else ('T' if max(r,g,b)-min(r,g,b)<30 else '.'))
   row.append(c)
  print(f'{y:02d} '+''.join(row))
PY"
